/**
 * Decorative, whole-quadrant bubble cover. The caller owns the accessible
 * button, the concealed result, and reveal state. Load styles/bubble-reveal.css.
 */
const SVG_NS = 'http://www.w3.org/2000/svg';
const POP_DURATION_MS = 220;
let nextOpticsId = 0;

function svgNode(doc, name, attributes = {}) {
  const node = doc.createElementNS(SVG_NS, name);
  for (const [key, value] of Object.entries(attributes)) node.setAttribute(key, String(value));
  return node;
}

function span(doc, suffix) {
  const node = doc.createElement('span');
  node.className = `bubble-reveal__${suffix}`;
  return node;
}

function gradient(doc, defs, name, attributes, stops) {
  const node = svgNode(doc, name, attributes);
  for (const [offset, color, opacity] of stops) {
    node.appendChild(svgNode(doc, 'stop', {
      offset, 'stop-color': color, 'stop-opacity': opacity,
    }));
  }
  defs.appendChild(node);
}

function createBadgeOptics(doc) {
  const id = `bubble-reveal-optics-${++nextOpticsId}`;
  const svg = svgNode(doc, 'svg', {
    class: 'bubble-reveal__badge-optics', viewBox: '-51 -51 102 102',
    'aria-hidden': 'true', focusable: 'false',
  });
  const defs = svgNode(doc, 'defs');
  gradient(doc, defs, 'radialGradient', {
    id: `${id}-volume`, gradientUnits: 'userSpaceOnUse', cx: -12, cy: -17, r: 61,
  }, [
    [0, 'white', .32], [.35, 'white', .08], [.52, '#14212c', 0],
    [.75, '#101a29', .18], [1, '#101a29', .73],
  ]);
  gradient(doc, defs, 'radialGradient', { id: `${id}-shine` }, [
    [0, 'white', .46], [.55, 'white', .14], [1, 'white', 0],
  ]);
  gradient(doc, defs, 'linearGradient', {
    id: `${id}-rim`, x1: 0, y1: 0, x2: 1, y2: 1,
  }, [
    [0, 'white', .38], [.4, 'white', 0], [.7, '#142536', .42], [1, 'white', .3],
  ]);
  svg.appendChild(defs);
  // Existing circular badge SVGs have a 102-unit viewBox and 35.2-unit rim.
  svg.appendChild(svgNode(doc, 'circle', { r: 35.2, fill: `url(#${id}-volume)` }));
  svg.appendChild(svgNode(doc, 'circle', {
    r: 34.8, fill: 'none', stroke: `url(#${id}-rim)`, 'stroke-width': .8,
  }));
  svg.appendChild(svgNode(doc, 'ellipse', {
    cx: -10, cy: -22, rx: 23, ry: 10, transform: 'rotate(-22)', fill: `url(#${id}-shine)`,
  }));
  svg.appendChild(svgNode(doc, 'path', {
    d: 'M-28-13 Q-20-30-4-29', fill: 'none', stroke: 'white',
    'stroke-opacity': .34, 'stroke-width': 1.2, 'stroke-linecap': 'round',
  }));
  return svg;
}

/** Decorative crown. Append beside the cover to keep it after the cover pops. */
export function createHeroCrown(doc) {
  const crown = span(doc, 'hero');
  crown.setAttribute('aria-hidden', 'true');
  const svg = svgNode(doc, 'svg', { viewBox: '0 0 32 24', focusable: 'false' });
  svg.appendChild(svgNode(doc, 'path', { d: 'M4 8l7 5L16 3l5 10 7-5-3 12H7z' }));
  svg.appendChild(svgNode(doc, 'path', {
    d: 'M8 23h16', fill: 'none', stroke: 'currentColor', 'stroke-width': 2,
    'stroke-linecap': 'round',
  }));
  for (const [cx, cy] of [[3, 6], [16, 2], [29, 6]]) {
    svg.appendChild(svgNode(doc, 'circle', { cx, cy, r: 2 }));
  }
  crown.appendChild(svg);
  return crown;
}

/**
 * @param {Document} doc
 * @param {{badgeSrc: string, color?: string, hero?: boolean}} options
 * @returns {{element: HTMLSpanElement, pop: Function, dispose: Function}}
 *
 * Pop is one-way and idempotent. Its completion removes the cover before
 * invoking onComplete. Instant/reduced-motion pops complete synchronously.
 * dispose() removes it and cancels any pending completion.
 */
export function createBubbleCover(doc, { badgeSrc, color, hero = false } = {}) {
  const view = doc.defaultView || globalThis;
  const schedule = (view.setTimeout || globalThis.setTimeout).bind(view);
  const cancel = (view.clearTimeout || globalThis.clearTimeout).bind(view);
  const element = doc.createElement('span');
  element.className = 'bubble-reveal';
  element.setAttribute('aria-hidden', 'true');
  element.style.setProperty('--bubble-reveal-duration', `${POP_DURATION_MS}ms`);
  if (color) element.style.setProperty('--bubble-reveal-color', color);

  const film = span(doc, 'film');
  for (const part of ['skin', 'dent', 'glint']) film.appendChild(span(doc, part));
  const badge = span(doc, 'badge');
  const art = doc.createElement('img');
  art.className = 'bubble-reveal__badge-art';
  art.alt = '';
  art.draggable = false;
  if (badgeSrc) art.src = badgeSrc;
  badge.appendChild(art);
  badge.appendChild(createBadgeOptics(doc));
  film.appendChild(badge);
  film.appendChild(span(doc, 'lowlight'));
  element.appendChild(film);
  element.appendChild(span(doc, 'burst'));
  if (hero) element.appendChild(createHeroCrown(doc));

  let state = 'covered';
  let timer = null;

  function pop(event, { instant = false, onComplete = () => {} } = {}) {
    if (state !== 'covered') return false;
    state = 'popping';

    const finish = () => {
      if (state !== 'popping') return;
      timer = null;
      state = 'complete';
      element.remove();
      onComplete();
    };
    if (instant || view.matchMedia?.('(prefers-reduced-motion: reduce)').matches) {
      finish();
      return true;
    }

    const bounds = element.getBoundingClientRect();
    const pointer = event?.detail > 0
      && Number.isFinite(event.clientX) && Number.isFinite(event.clientY);
    const clamp = value => Math.max(0, Math.min(1, value));
    const x = pointer && bounds.width > 0 ? clamp((event.clientX - bounds.left) / bounds.width) : .5;
    const y = pointer && bounds.height > 0 ? clamp((event.clientY - bounds.top) / bounds.height) : .5;
    // Pointer fractions use screen-space bounds; the CSS mask radius uses
    // local layout pixels so scaled ticket ancestors cannot truncate the hole.
    const width = element.clientWidth || bounds.width;
    const height = element.clientHeight || bounds.height;
    const radius = Math.hypot(
      Math.max(x, 1 - x) * width,
      Math.max(y, 1 - y) * height,
    ) + 4;
    element.style.setProperty('--bubble-reveal-pop-x', `${x * 100}%`);
    element.style.setProperty('--bubble-reveal-pop-y', `${y * 100}%`);
    element.style.setProperty('--bubble-reveal-pop-radius', `${radius}px`);
    element.classList.add('is-popping');
    timer = schedule(finish, POP_DURATION_MS);
    return true;
  }

  function dispose() {
    if (timer !== null) cancel(timer);
    timer = null;
    state = 'disposed';
    element.remove();
  }

  return { element, pop, dispose };
}
